import os
from typing import Any, Dict, Iterable, Optional

import requests


class Auth0FederatedProfileError(Exception):
    pass


def _coalesce(*values: Any) -> Optional[Any]:
    for value in values:
        if value is not None and value != "":
            return value
    return None


def _split_name(full_name: Optional[str]) -> Dict[str, Optional[str]]:
    if not full_name:
        return {"given_name": None, "family_name": None}
    parts = full_name.strip().split()
    if not parts:
        return {"given_name": None, "family_name": None}
    if len(parts) == 1:
        return {"given_name": parts[0], "family_name": None}
    return {"given_name": parts[0], "family_name": " ".join(parts[1:])}


def _normalize_scopes(scope_value: Any) -> Iterable[str]:
    if scope_value is None:
        return []
    if isinstance(scope_value, str):
        return [s for s in scope_value.strip().split() if s]
    if isinstance(scope_value, (list, tuple, set)):
        return [str(s) for s in scope_value if s]
    return [str(scope_value)]


def _extract_identities(userinfo: Dict[str, Any]) -> Dict[str, Any]:
    identities = userinfo.get("identities")
    if isinstance(identities, list) and identities:
        first = identities[0] or {}
        if isinstance(first, dict):
            return {
                "provider": first.get("provider"),
                "user_id": first.get("user_id"),
                "connection": first.get("connection"),
                "is_social": first.get("isSocial"),
            }
    sub = userinfo.get("sub")
    if isinstance(sub, str) and "|" in sub:
        provider, provider_user_id = sub.split("|", 1)
        return {
            "provider": provider,
            "user_id": provider_user_id,
            "connection": None,
            "is_social": None,
        }
    return {
        "provider": None,
        "user_id": None,
        "connection": None,
        "is_social": None,
    }


def fetch_and_normalize_federated_profile(
    access_token: str,
    auth0_domain: Optional[str] = None,
    timeout: float = 10.0,
) -> Dict[str, Any]:
    if not access_token:
        raise ValueError("access_token is required")

    domain = (auth0_domain or os.getenv("AUTH0_DOMAIN", "")).strip()
    if not domain:
        raise ValueError("Auth0 domain is required via auth0_domain or AUTH0_DOMAIN")

    if domain.startswith("https://"):
        base_url = domain.rstrip("/")
    else:
        base_url = f"https://{domain.rstrip('/')}"

    userinfo_url = f"{base_url}/userinfo"

    response = requests.get(
        userinfo_url,
        headers={
            "Authorization": f"Bearer {access_token}",
            "Accept": "application/json",
        },
        timeout=timeout,
    )

    if response.status_code != 200:
        raise Auth0FederatedProfileError(
            f"Auth0 /userinfo request failed with status {response.status_code}: {response.text}"
        )

    userinfo = response.json()
    identities = _extract_identities(userinfo)
    split_name = _split_name(_coalesce(userinfo.get("name"), userinfo.get("nickname")))

    normalized = {
        "provider": identities["provider"],
        "provider_user_id": _coalesce(identities["user_id"], userinfo.get("sub")),
        "subject": userinfo.get("sub"),
        "connection": identities["connection"],
        "is_social": identities["is_social"],
        "email": userinfo.get("email"),
        "email_verified": userinfo.get("email_verified"),
        "phone_number": userinfo.get("phone_number"),
        "phone_number_verified": userinfo.get("phone_number_verified"),
        "name": _coalesce(userinfo.get("name"), userinfo.get("nickname")),
        "given_name": _coalesce(userinfo.get("given_name"), split_name["given_name"]),
        "family_name": _coalesce(userinfo.get("family_name"), split_name["family_name"]),
        "middle_name": userinfo.get("middle_name"),
        "nickname": userinfo.get("nickname"),
        "preferred_username": userinfo.get("preferred_username"),
        "profile": userinfo.get("profile"),
        "picture": userinfo.get("picture"),
        "website": userinfo.get("website"),
        "gender": userinfo.get("gender"),
        "birthdate": userinfo.get("birthdate"),
        "zoneinfo": userinfo.get("zoneinfo"),
        "locale": userinfo.get("locale"),
        "updated_at": userinfo.get("updated_at"),
        "address": userinfo.get("address"),
        "raw_claims": userinfo,
        "scopes": list(_normalize_scopes(userinfo.get("scope"))),
    }

    return normalized
